// Evidence-based, offline pilot assessment. This code never calls a model API,
// approves spending, or certifies that a PNG was generated by AI.
const REVIEW_AXES=Object.freeze(['reference_identity','part_identity','line_and_color','transparent_background','part_alignment','hidden_surface']);
const validHash=s=>typeof s==='string'&&/^[a-f0-9]{64}$/.test(s);
const need=(condition,message)=>{if(!condition)throw new Error(message);};
const object=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
const usd=v=>typeof v==='number'&&Number.isFinite(v)&&v>=0&&Math.round(v*1e6)===v*1e6;

// visualReview is a human report, never proof of authentic AI generation.
// billing is optionally an unverified manual transcription, never a payment authorization.
export function assessTwoCallPilot({plan,structureReport=null,visualReview=null,billing=null}){
  need(object(plan)&&plan.version===2&&validHash(plan.plan_id)&&typeof plan.model==='string'&&
    plan.trial_counts?.maximum_requests===2&&Array.isArray(plan.requests)&&
    plan.requests.length===2&&plan.requests[0]?.id==='reference'&&plan.requests[1]?.id==='iris_l',
    'A validated two-call plan is required.');
  need(plan.budget_policy?.owner_approved===false&&plan.cost?.permitted_api_calls===0,
    'This offline assessment accepts only the original, unapproved two-call plan.');
  let structure='not-tested',partSha=null;
  if(structureReport!==null){
    need(object(structureReport)&&structureReport.format==='ai-live2d-pilot-structure-review'&&
      structureReport.version===1&&structureReport.plan_id===plan.plan_id&&
      structureReport.model===plan.model&&Array.isArray(structureReport.parts)&&structureReport.parts.length===1&&
      structureReport.parts[0]?.role==='iris_l'&&validHash(structureReport.parts[0]?.source_sha256)&&
      typeof structureReport.parts[0]?.structure_passed==='boolean',
    'The structural report must match this plan and contain exactly one iris_l result.');
    const good=structureReport.parts[0].structure_passed;
    need(structureReport.all_structure_passed===good,'Structure summary conflicts with part evidence.');
    structure=good?'passed':'failed';partSha=structureReport.parts[0].source_sha256;
  }
  let review=null;
  if(visualReview!==null){
    need(object(visualReview)&&Object.keys(visualReview).sort().join(',')===['assessor','axes','part_sha256','reference_sha256'].sort().join(',')&&
      typeof visualReview.assessor==='string'&&visualReview.assessor.trim().length>=2&&visualReview.assessor.length<=80&&
      validHash(visualReview.reference_sha256)&&validHash(visualReview.part_sha256)&&object(visualReview.axes)&&
      Object.keys(visualReview.axes).sort().join(',')===REVIEW_AXES.slice().sort().join(','),
      'A complete, attributed visual review with both image hashes is required.');
    need(partSha===visualReview.part_sha256&&structure==='passed','Review must reference the structurally passing part.');
    for(const axis of REVIEW_AXES)need(['pass','fail','not-tested'].includes(visualReview.axes[axis]),'Each visual axis must be pass, fail, or not-tested.');
    review={assessor:visualReview.assessor.trim(),reference_sha256:visualReview.reference_sha256,part_sha256:partSha,
      axes:structuredClone(visualReview.axes),passed:REVIEW_AXES.every(axis=>visualReview.axes[axis]==='pass'),
      human_assessment_only:true};
  }
  let reportedBilling=null;
  if(billing!==null){
    need(object(billing)&&Object.keys(billing).sort().join(',')===['currency','reference_usd','iris_l_usd','source'].sort().join(',')&&
      billing.currency==='USD'&&['dashboard-transcription','api-usage-transcription'].includes(billing.source)&&
      usd(billing.reference_usd)&&usd(billing.iris_l_usd),
      'Billing must be a bounded manual USD transcription, not a synthetic quote.');
    // Store integer microUSD to avoid floating point drift when adding charges.
    const reference=Math.round(billing.reference_usd*1e6),part=Math.round(billing.iris_l_usd*1e6);
    need(reference+part<=1e10,'Reject implausibly large billing transcription.');
    reportedBilling={currency:'USD',reference_microusd:reference,iris_l_microusd:part,
      total_microusd:reference+part,source:billing.source,provider_billing_verified:false};
  }
  const blockers=[];
  if(structure==='not-tested')blockers.push('Real iris_l PNG has not passed structural inspection.');
  if(structure==='failed')blockers.push('Part failed RGBA/placement structural inspection.');
  if(!review)blockers.push('Canonical reference and part have not been jointly reviewed by a human.');
  else if(!review.passed)blockers.push('One or more appearance checks failed or were not tested.');
  if(!reportedBilling)blockers.push('Observed per-request spend has not been recorded.');
  blockers.push('Authenticated AI provider provenance is not yet implemented.');
  blockers.push('33-layer AI output and its Inochi2D model are not verified.');
  return {format:'ai-live2d-two-call-evidence-assessment',version:1,
    plan_id:plan.plan_id,model:plan.model,scope:'reference-and-one-iris-only',
    part_structure:structure,part_sha256:partSha,visual_review:review,billing_transcription:reportedBilling,
    evidence_complete_for_two_call_review:structure==='passed'&&review?.passed===true&&Boolean(reportedBilling),
    authenticated_ai_provenance_verified:false,complete_33_part_batch:false,inochi_model_verified:false,
    ready_for_general_publication:false,ready_for_paid_generation:false,blockers,
    disclaimer:'Offline evidence summary only: no API request, payment, provenance verification, model generation or owner authorization.'};
}

export function planPilotMetrics(reviews){
  need(Array.isArray(reviews)&&reviews.length<=1000,'Expected no more than 1000 offline review records.');
  const ids=new Set(),statuses={not_tested:0,structure_failed:0,structure_passed:0,visual_review_passed:0},observedCosts=[];
  for(const r of reviews){
    need(object(r)&&r.format==='ai-live2d-two-call-evidence-assessment'&&validHash(r.plan_id)&&!ids.has(r.plan_id),
      'Only distinct assessment records are accepted.');
    ids.add(r.plan_id);
    if(r.part_structure==='not-tested')statuses.not_tested++;
    else if(r.part_structure==='failed')statuses.structure_failed++;
    else if(r.part_structure==='passed')statuses.structure_passed++;
    else throw new Error('Unknown structure status.');
    if(r.visual_review?.passed===true)statuses.visual_review_passed++;
    if(r.billing_transcription?.total_microusd!==undefined){
      need(Number.isSafeInteger(r.billing_transcription.total_microusd)&&r.billing_transcription.total_microusd>=0,
        'Invalid manually recorded cost.');
      observedCosts.push(r.billing_transcription.total_microusd);
    }
  }
  const attempted=statuses.structure_failed+statuses.structure_passed;
  return {format:'ai-live2d-offline-pilot-metrics',version:1,plan_count:reviews.length,
    structurally_inspected_count:attempted,structure_pass_count:statuses.structure_passed,
    structural_pass_rate:attempted?statuses.structure_passed/attempted:null,
    human_visual_pass_count:statuses.visual_review_passed,
    visual_pass_rate:attempted?statuses.visual_review_passed/attempted:null,
    cost_samples:observedCosts.length,
    mean_manually_reported_cost_microusd:observedCosts.length?Math.round(observedCosts.reduce((a,b)=>a+b,0)/observedCosts.length):null,
    ai_generation_success_rate:null,ready_for_publication:false,
    limitation:'Pilot evidence is not an authenticated AI run or a statistically valid 33-part success rate.'};
}
